	retained:=map[ManagedPathID]bool{PathAuthnConfig:true,PathProductUpdateTrust:true,PathDatabaseConfig:true,PathDNSConfig:true,PathFTPConfig:true,PathPostfixConfig:true,PathDovecotConfig:true}
	retainedRoot:=filepath.Join(installerRoot,"retained",state.ReleaseID);if purge{if err:=secureMkdir(retainedRoot,0700);err!=nil{return MutationReceipt{},err}}
	for pathID:=range closedPaths{
		destination:=managedPath(pathID)
		if retained[pathID]&&purge{
			source:=managedSlotPath(state.ActiveSlot,pathID);info,statErr:=os.Stat(source)
			if statErr!=nil&&pathID==PathProductUpdateTrust{return MutationReceipt{},statErr}
			if statErr==nil&&info.Mode().IsRegular(){payload,readErr:=os.ReadFile(source);if readErr!=nil{return MutationReceipt{},readErr};owner,group,_:=managedFilePolicy(pathID);uid,gid,identityErr:=identityIDs(owner,group);if identityErr!=nil{return MutationReceipt{},identityErr};retainedPath:=filepath.Join(retainedRoot,string(pathID));if err:=atomicWriteManaged(retainedPath,payload,info.Mode().Perm()&0770,uid,gid);err!=nil{return MutationReceipt{},err};if pathID==PathProductUpdateTrust{if err:=installProductUpdateTrust(retainedPath,destination);err!=nil{return MutationReceipt{},err};continue};temporary:=destination+".new";_ = os.Remove(temporary);if err:=os.Symlink(retainedPath,temporary);err!=nil{return MutationReceipt{},err};if err:=os.Rename(temporary,destination);err!=nil{return MutationReceipt{},err};continue}
		}
		_ = os.Remove(destination)
	}
	_,_ = runFixed(ctx,"/usr/bin/systemctl","daemon-reload")
	if purge{for _,slot:=range []SlotID{SlotA,SlotB}{target:=filepath.Join(slotRoot,string(slot));if strings.HasPrefix(target,slotRoot+string(os.PathSeparator)){_ = os.RemoveAll(target)}}}
	return mutation("deactivate",state.ReleaseID,digestText(strconv.FormatBool(purge)),host.now()),nil
