func (host *LinuxHost)Export(ctx context.Context,state InstalledState,path string)(ExportReceipt,error){if err:=state.Validate();err!=nil{return ExportReceipt{},err};clean:=filepath.Clean(path);if !filepath.IsAbs(clean)||!strings.HasPrefix(clean,exportRoot+string(os.PathSeparator))||filepath.Ext(clean)!=".gz"{return ExportReceipt{},ErrInvalid};if existing,err:=inspectExport(clean);err==nil{return existing,nil}else if !os.IsNotExist(err){return ExportReceipt{},err};if err:=secureMkdir(exportRoot,0700);err!=nil{return ExportReceipt{},err};file,err:=os.OpenFile(clean,os.O_CREATE|os.O_EXCL|os.O_WRONLY|syscall.O_NOFOLLOW,0600);if err!=nil{return ExportReceipt{},err};hasher:=sha256.New();counting:=&countWriter{writer:io.MultiWriter(file,hasher)};gzipWriter:=gzip.NewWriter(counting);archive:=tar.NewWriter(gzipWriter);manifest:=[]string{};roots:=[]string{"/etc/cyberpanel",installerRoot,"/var/lib/cyberpanel",filepath.Join(slotRoot,string(state.ActiveSlot),"managed")};for _,root:=range roots{if err:=appendExportTree(ctx,archive,root,&manifest);err!=nil{archive.Close();gzipWriter.Close();file.Close();_ = os.Remove(clean);return ExportReceipt{},err}};sort.Strings(manifest);manifestPayload:=[]byte(strings.Join(manifest,"\n")+"\n");header:=&tar.Header{Name:"MANIFEST.sha256",Mode:0600,Size:int64(len(manifestPayload)),ModTime:host.now()};if err:=archive.WriteHeader(header);err==nil{_,err=archive.Write(manifestPayload)};closeErr:=errors.Join(archive.Close(),gzipWriter.Close(),file.Sync(),file.Close());if err!=nil||closeErr!=nil{_ = os.Remove(clean);return ExportReceipt{},errors.Join(err,closeErr)};manifestDigest:=digestText(string(manifestPayload));return ExportReceipt{Path:clean,Digest:hex.EncodeToString(hasher.Sum(nil)),ManifestDigest:manifestDigest,Bytes:counting.count,CompletedAt:host.now()},nil}
func (host *LinuxHost)CleanupTransaction(ctx context.Context,plan TransactionPlan,success bool)error{if !safeID.MatchString(plan.ID){return ErrInvalid};path:=filepath.Join(stagingRoot,plan.ID);if !strings.HasPrefix(path,stagingRoot+string(os.PathSeparator)){return ErrIntegrity};cleanupErr:=os.RemoveAll(path);if !success&&(plan.TargetSlot==SlotA||plan.TargetSlot==SlotB){active,_,activeErr:=host.CurrentSlot(ctx);if activeErr!=nil||active!=plan.TargetSlot{target:=filepath.Join(slotRoot,string(plan.TargetSlot));if strings.HasPrefix(target,slotRoot+string(os.PathSeparator)){cleanupErr=errors.Join(cleanupErr,os.RemoveAll(target))}}else if plan.Kind==TransactionInstall{_ = os.Remove(activeLink);for id:=range closedPaths{destination:=managedPath(id);if id==PathProductUpdateTrust{_ = os.Remove(destination);continue};source:=managedSlotPath(plan.TargetSlot,id);if target,err:=filepath.EvalSymlinks(destination);err==nil&&target==source{_ = os.Remove(destination)}};for _,unit:=range []string{"panel-update-fetchd.service","panel-gateway.service","panel-core.service","panel-providerd.service","panel-authd.service","panel-secretd.service","panel-execd.service","lsws.service","panel-updated.service"}{_,_ = runFixed(ctx,"/usr/bin/systemctl","disable","--now",unit)};target:=filepath.Join(slotRoot,string(plan.TargetSlot));cleanupErr=errors.Join(cleanupErr,os.RemoveAll(target))}};return cleanupErr}

func parseOSRelease()(map[string]string,error){payload,err:=os.ReadFile("/etc/os-release");if err!=nil{return nil,err};result:=map[string]string{};for _,line:=range strings.Split(string(payload),"\n"){key,value,ok:=strings.Cut(line,"=");if !ok||key==""{continue};result[key]=strings.Trim(strings.TrimSpace(value),"\"")};return result,nil}
func dialPublicHTTPS(ctx context.Context,network,address string)(net.Conn,error){host,port,err:=net.SplitHostPort(address);if err!=nil{return nil,err};addresses,err:=net.DefaultResolver.LookupIPAddr(ctx,host);if err!=nil{return nil,err};dialer:=net.Dialer{Timeout:30*time.Second,KeepAlive:30*time.Second};for _,candidate:=range addresses{ip:=candidate.IP;if !ip.IsGlobalUnicast()||ip.IsPrivate()||ip.IsLoopback()||ip.IsLinkLocalUnicast()||ip.IsLinkLocalMulticast(){continue};connection,err:=dialer.DialContext(ctx,network,net.JoinHostPort(ip.String(),port));if err==nil{return connection,nil}};return nil,ErrIntegrity}
func majorRelease(value string)string{if before,_,ok:=strings.Cut(value,".");ok{return before};return value}
func readTrimmed(path string)(string,error){payload,err:=os.ReadFile(path);if err!=nil{return "",err};return strings.TrimSpace(string(payload)),nil}
func readMemory()uint64{payload,_:=os.ReadFile("/proc/meminfo");for _,line:=range strings.Split(string(payload),"\n"){fields:=strings.Fields(line);if len(fields)>=2&&fields[0]=="MemTotal:"{value,_:=strconv.ParseUint(fields[1],10,64);return value*1024}};return 0}
func diskFacts(path string)(uint64,string,error){var stat syscall.Statfs_t;if err:=syscall.Statfs(path,&stat);err!=nil{return 0,"",err};return stat.Bavail*uint64(stat.Bsize),fmt.Sprintf("0x%x",stat.Type),nil}
func runtimeCPUCount()int{payload,_:=os.ReadFile("/proc/cpuinfo");count:=strings.Count(string(payload),"\nprocessor");if strings.HasPrefix(string(payload),"processor"){count++};if count<1{return 1};return count}
func occupiedTCPPorts()([]uint16,error){seen:=map[uint16]bool{};for _,path:=range []string{"/proc/net/tcp","/proc/net/tcp6"}{payload,err:=os.ReadFile(path);if err!=nil{continue};for _,line:=range strings.Split(string(payload),"\n")[1:]{fields:=strings.Fields(line);if len(fields)<4||fields[3]!="0A"{continue};_,portText,ok:=strings.Cut(fields[1],":");if !ok{continue};port,err:=strconv.ParseUint(portText,16,16);if err==nil{seen[uint16(port)]=true}}};ports:=make([]uint16,0,len(seen));for port:=range seen{ports=append(ports,port)};sort.Slice(ports,func(i,j int)bool{return ports[i]<ports[j]});return ports,nil}

func secureMkdir(path string,mode os.FileMode)error{clean:=filepath.Clean(path);if !filepath.IsAbs(clean){return ErrInvalid};current:=string(os.PathSeparator);for _,part:=range strings.Split(strings.TrimPrefix(clean,string(os.PathSeparator)),string(os.PathSeparator)){current=filepath.Join(current,part);info,err:=os.Lstat(current);if os.IsNotExist(err){if err:=os.Mkdir(current,mode);err!=nil{return err};continue};if err!=nil{return err};if info.Mode()&os.ModeSymlink!=0||!info.IsDir(){return ErrIntegrity}};return os.Chmod(clean,mode)}
func runFixed(ctx context.Context,executable string,arguments ...string)(string,error){allowed:=map[string]bool{"/usr/sbin/useradd":true,"/usr/sbin/usermod":true,"/usr/bin/apt-get":true,"/usr/bin/dnf":true,"/usr/bin/systemctl":true,"/usr/bin/systemd-tmpfiles":true};if !allowed[executable]{return "",ErrUnsupported};command:=exec.CommandContext(ctx,executable,arguments...);command.Env=[]string{"PATH=/usr/sbin:/usr/bin:/sbin:/bin","LANG=C.UTF-8","LC_ALL=C.UTF-8","DEBIAN_FRONTEND=noninteractive"};output,err:=command.CombinedOutput();if len(output)>1<<20{output=output[:1<<20]};if err!=nil{return string(output),fmt.Errorf("%s: %w",filepath.Base(executable),err)};return string(output),nil}

func ensureContainerSubordinateIDs(ctx context.Context,name string)error{const count uint64=65536;uidRanges,uidPresent,err:=readSubordinateRanges("/etc/subuid",name);if err!=nil{return err};gidRanges,gidPresent,err:=readSubordinateRanges("/etc/subgid",name);if err!=nil{return err};if uidPresent&&gidPresent{return nil};occupied:=append(uidRanges,gidRanges...);start:=uint64(524288);for{end:=start+count-1;conflict:=false;for _,entry:=range occupied{if start<=entry[1]&&entry[0]<=end{conflict=true;break}};if !conflict{span:=strconv.FormatUint(start,10)+"-"+strconv.FormatUint(end,10);arguments:=[]string{};if !uidPresent{arguments=append(arguments,"--add-subuids",span)};if !gidPresent{arguments=append(arguments,"--add-subgids",span)};arguments=append(arguments,name);_,err=runFixed(ctx,"/usr/sbin/usermod",arguments...);return err};start+=count;if start>1<<31{return ErrIntegrity}}}
func readSubordinateRanges(path,name string)([][2]uint64,bool,error){content,err:=os.ReadFile(path);if errors.Is(err,os.ErrNotExist){return nil,false,nil};if err!=nil{return nil,false,err};ranges:=make([][2]uint64,0);present:=false;for _,line:=range strings.Split(string(content),"\n"){fields:=strings.Split(line,":");if len(fields)!=3{continue};start,startErr:=strconv.ParseUint(fields[1],10,64);count,countErr:=strconv.ParseUint(fields[2],10,64);if startErr!=nil||countErr!=nil||count==0||start+count<start{return nil,false,ErrIntegrity};ranges=append(ranges,[2]uint64{start,start+count-1});if fields[0]==name&&count>=65536{present=true}};return ranges,present,nil}

func identityRecord(identity IdentityID)(string,string,string){switch identity{case IdentityPanel:return "cyberpanel","/var/lib/cyberpanel/control","/usr/sbin/nologin";case IdentityGateway:return "cyberpanel-gateway","/var/lib/cyberpanel-gateway","/usr/sbin/nologin";case IdentityAuthn:return "cyberpanel-auth","/var/lib/cyberpanel-auth","/usr/sbin/nologin";case IdentitySecrets:return "cyberpanel-secrets","/var/lib/cyberpanel-secrets","/usr/sbin/nologin";case IdentityContainers:return "cyberpanel-containers","/var/lib/cyberpanel-containers","/usr/sbin/nologin";case IdentityWebAdmin:return "lsadm","/var/lib/lsadm","/usr/sbin/nologin"};return "","",""}
func identityIDs(owner,group IdentityID)(int,int,error){uid:=0;gid:=0;if owner!=IdentityRoot{account,err:=user.Lookup(identityName(owner));if err!=nil{return 0,0,err};parsed,err:=strconv.Atoi(account.Uid);if err!=nil||parsed==0{return 0,0,ErrIntegrity};uid=parsed};if group!=IdentityRoot{account,err:=user.Lookup(identityName(group));if err!=nil{return 0,0,err};parsed,err:=strconv.Atoi(account.Gid);if err!=nil||parsed==0{return 0,0,ErrIntegrity};gid=parsed};return uid,gid,nil}
func identityName(identity IdentityID)string{if identity==IdentityRoot{return "root"};name,_,_:=identityRecord(identity);return name}
