func extractTarGzip(source,destination string)error{file,err:=os.Open(source);if err!=nil{return err};defer file.Close();gzipReader,err:=gzip.NewReader(file);if err!=nil{return err};defer gzipReader.Close();archive:=tar.NewReader(gzipReader);var total int64;for{header,err:=archive.Next();if errors.Is(err,io.EOF){break};if err!=nil{return err};clean:=filepath.Clean(header.Name);if clean=="."||filepath.IsAbs(clean)||strings.HasPrefix(clean,".."+string(os.PathSeparator))||strings.Contains(clean,"\\"){return ErrIntegrity};target:=filepath.Join(destination,clean);if !strings.HasPrefix(target,destination+string(os.PathSeparator)){return ErrIntegrity};switch header.Typeflag{case tar.TypeDir:if err:=secureMkdir(target,0755);err!=nil{return err};case tar.TypeReg,tar.TypeRegA:if header.Size<0||header.Size>4<<30{return ErrIntegrity};total+=header.Size;if total>16<<30{return ErrIntegrity};if err:=secureMkdir(filepath.Dir(target),0755);err!=nil{return err};mode:=os.FileMode(header.Mode)&0755;if mode&0111==0{mode=0644};output,err:=os.OpenFile(target,os.O_CREATE|os.O_EXCL|os.O_WRONLY|syscall.O_NOFOLLOW,mode);if err!=nil{return err};written,copyErr:=io.Copy(output,io.LimitReader(archive,header.Size+1));closeErr:=output.Close();if copyErr!=nil||closeErr!=nil||written!=header.Size{return errors.Join(ErrIntegrity,copyErr,closeErr)};default:return ErrIntegrity}};return nil}
func copyRegular(source,target string,mode os.FileMode)error{input,err:=os.Open(source);if err!=nil{return err};defer input.Close();output,err:=os.OpenFile(target,os.O_CREATE|os.O_EXCL|os.O_WRONLY|syscall.O_NOFOLLOW,mode);if err!=nil{return err};_,copyErr:=io.Copy(output,input);closeErr:=output.Close();return errors.Join(copyErr,closeErr)}
func digestTree(root string)(string,error){paths:=[]string{};if err:=filepath.Walk(root,func(path string,info os.FileInfo,err error)error{if err!=nil{return err};if path==root{return nil};if info.Mode()&os.ModeSymlink!=0||!info.Mode().IsRegular()&&!info.IsDir(){return ErrIntegrity};relative,err:=filepath.Rel(root,path);if err!=nil{return err};paths=append(paths,relative);return nil});err!=nil{return "",err};sort.Strings(paths);hasher:=sha256.New();for _,relative:=range paths{path:=filepath.Join(root,relative);info,err:=os.Stat(path);if err!=nil{return "",err};io.WriteString(hasher,relative+"\x00"+info.Mode().String()+"\x00");if info.Mode().IsRegular(){file,err:=os.Open(path);if err!=nil{return "",err};_,copyErr:=io.Copy(hasher,file);closeErr:=file.Close();if copyErr!=nil||closeErr!=nil{return "",errors.Join(copyErr,closeErr)}}};return hex.EncodeToString(hasher.Sum(nil)),nil}

func probeService(ctx context.Context,distribution Distribution,spec ServiceSpec)(string,error){unit,err:=nativeService(distribution,spec.ID);if err!=nil{return "",err};output,err:=runFixed(ctx,"/usr/bin/systemctl","is-active",unit);if err!=nil{return output,err};if spec.Health==HealthServiceActive{return strings.TrimSpace(output),nil};network,address:=healthAddress(spec.Health);if network=="unix"{connection,err:=net.DialTimeout(network,address,time.Second);if err!=nil{return output,err};connection.Close();return strings.TrimSpace(output)+":socket",nil};connection,err:=net.DialTimeout(network,address,time.Second);if err!=nil{return output,err};connection.Close();return strings.TrimSpace(output)+":"+address,nil}
func healthAddress(check HealthCheckID)(string,string){switch check{case HealthAuthnSocket:return "unix","/run/cyberpanel-auth/auth-verifier.sock";case HealthSecretsSocket:return "unix","/run/cyberpanel-secrets/material.sock";case HealthExecutorSocket:return "unix","/run/cyberpanel/panel-execd.sock";case HealthPanelAPI:return "tcp","127.0.0.1:8090";case HealthWebHTTP:return "tcp","127.0.0.1:80";case HealthDatabaseLocal:return "tcp","127.0.0.1:3306";case HealthDNSLocal:return "tcp","127.0.0.1:53";case HealthFTP:return "tcp","127.0.0.1:21";case HealthSMTP:return "tcp","127.0.0.1:25";case HealthIMAP:return "tcp","127.0.0.1:143";case HealthRspamd:return "tcp","127.0.0.1:11334";case HealthClamAV:return "tcp","127.0.0.1:3310";case HealthRedis:return "tcp","127.0.0.1:6379";case HealthMemcached:return "tcp","127.0.0.1:11211"};return "tcp","127.0.0.1:9"}
type countWriter struct{writer io.Writer;count uint64}
func (writer *countWriter)Write(payload []byte)(int,error){count,err:=writer.writer.Write(payload);writer.count+=uint64(count);return count,err}
func inspectExport(path string)(ExportReceipt,error){info,err:=os.Stat(path);if err!=nil{return ExportReceipt{},err};if err:=requireRootOwned(info,0600);err!=nil{return ExportReceipt{},err};digest,size,err:=hashFile(path);if err!=nil{return ExportReceipt{},err};file,err:=os.Open(path);if err!=nil{return ExportReceipt{},err};defer file.Close();compressed,err:=gzip.NewReader(file);if err!=nil{return ExportReceipt{},ErrIntegrity};defer compressed.Close();archive:=tar.NewReader(compressed);manifest:=[]byte(nil);for{header,nextErr:=archive.Next();if errors.Is(nextErr,io.EOF){break};if nextErr!=nil{return ExportReceipt{},ErrIntegrity};if header.Name=="MANIFEST.sha256"{if header.Size<1||header.Size>16<<20{return ExportReceipt{},ErrIntegrity};manifest,err=io.ReadAll(io.LimitReader(archive,header.Size+1));if err!=nil||int64(len(manifest))!=header.Size{return ExportReceipt{},ErrIntegrity}}};if len(manifest)==0{return ExportReceipt{},ErrIntegrity};return ExportReceipt{Path:path,Digest:digest,ManifestDigest:digestText(string(manifest)),Bytes:uint64(size),CompletedAt:info.ModTime().UTC()},nil}
func appendExportTree(ctx context.Context,archive *tar.Writer,root string,manifest *[]string)error{info,err:=os.Lstat(root);if os.IsNotExist(err){return nil};if err!=nil{return err};_ = info;base:=strings.TrimPrefix(filepath.Clean(root),"/");return filepath.Walk(root,func(path string,entry os.FileInfo,walkErr error)error{if walkErr!=nil{return walkErr};select{case <-ctx.Done():return ctx.Err();default:};if entry.Mode()&os.ModeSymlink!=0{return nil};relative,err:=filepath.Rel(root,path);if err!=nil{return err};name:=filepath.Join(base,relative);if relative=="."{name=base};header,err:=tar.FileInfoHeader(entry,"");if err!=nil{return err};header.Name=name;header.Uid=0;header.Gid=0;header.Uname="root";header.Gname="root";header.Mode&=0770;if err:=archive.WriteHeader(header);err!=nil{return err};if entry.Mode().IsRegular(){file,err:=os.Open(path);if err!=nil{return err};hasher:=sha256.New();_,copyErr:=io.Copy(io.MultiWriter(archive,hasher),file);closeErr:=file.Close();if copyErr!=nil||closeErr!=nil{return errors.Join(copyErr,closeErr)};*manifest=append(*manifest,hex.EncodeToString(hasher.Sum(nil))+"  "+name)};return nil})}
